PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?husband ?birthPlace WHERE {
  dbr:Marisabel_Rodríguez_de_Chávez dbp:spouse ?husband .
  OPTIONAL { ?husband dbp:birthPlace ?bp . }
  OPTIONAL { ?husband dbo:birthPlace ?bp2 . }
  BIND (COALESCE(?bp, ?bp2) AS ?birthPlace)
}
LIMIT 100

